// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address firstOwner, address secondOwner) public {
        // 1. Admissible domain: firstOwner can be anything including address(0),
        // but secondOwner must be different from firstOwner so we can observe a change.
        // We exclude the case where both are the same to avoid a trivially passing case.
        vm.assume(firstOwner != secondOwner);

        // 2. The first call is made by the admin (msg.sender of constructor is this test contract's setUp caller?
        // Actually setUp runs under the test contract's address. We need to prank as the admin.
        // The admin is set in the constructor as msg.sender. In setUp, new C() is called by the test contract,
        // so the admin is address(this) (InvMutTest). So we prank as admin for the first call.
        vm.prank(address(this));
        c.setOwner(firstOwner);
        // Now owner should be firstOwner.

        // 3. On the buggy version, owner is reset to address(0) and no longer equals firstOwner.
        // We now attempt a second setOwner call, pranking as admin again.
        // The bug makes the subsequent owner check in onlyOwner (if used) fail, but here we don't use onlyOwner.
        // The rule: after the second successful setOwner, owner getter must return secondOwner.
        // The bug sets owner to address(0) after assignment, so the rule is violated.
        vm.prank(address(this));
        c.setOwner(secondOwner);
        assertTrue(c.owner() == secondOwner);
    }
}

